let productSelection='',productComparison='budget',currentProducts=[];
function productKey(s){return clean(s).toLowerCase().replace(/vat expenses|production|sales\s*:|ms product/gi,'').replace(/rickshow/g,'rickshaw').replace(/[^a-z0-9]/g,'');}
function productDefinitions(){const rows=[...new Map(records.income.map(x=>[x.r,x])).values()],map=new Map();for(const [field,group] of [['gross','sales value'],['volume','sales volume'],['production','production']])for(const x of rows.filter(x=>x.group.toLowerCase().includes(group)&&!/^total\b/i.test(x.label))){const key=productKey(x.label);if(!map.has(key))map.set(key,{key,name:x.label.replace(/\s+Production$/i,'').replace(/^Sales\s*:\s*/i,''),rows:{}});map.get(key).rows[field]=x.r;}const details=[...new Map((records.detail||[]).map(x=>[x.r,x])).values()];for(const p of map.values()){const vat=details.filter(x=>/^VAT Expenses/i.test(x.label)&&productKey(x.label)===p.key);if(vat.length===1)p.rows.vat=vat[0].r;}return [...map.values()];}
function productSpec(){return {type:productComparison==='budget'?'Budget':'Actual',year:productComparison==='budget'?+state.year:+productComparison,months:ids()};}
function productMeasure(p,selected=ids(),year=+state.year,type='Actual'){const get=(field,kind='income')=>p.rows[field]===undefined?null:val(p.rows[field],type,kind,selected,year),gross=get('gross'),vat=get('vat','detail'),volume=get('volume'),production=get('production'),net=sub(gross,vat),selling=net!==null&&volume!==null&&volume>0?net/(volume*1000):null,total=val(27,type,'income',selected,year);return {gross,vat,net,volume,production,selling,cost:null,spread:null,share:gross!==null&&total!==null&&total>0?gross/total*100:null,flow:sub(production,volume)};}
function productTrend(p,kind){const ms=[...new Set(records.income.filter(x=>x.year===+state.year&&x.type==='Actual'&&x.value!==null).map(x=>x.month))].sort((a,b)=>a-b),series=kind==='price'?[['selling','Selling value / kg','#087f8c']]:[['production','Production MT','#087f8c'],['volume','Sales MT','#31546b']],points=ms.map(month=>({month,...productMeasure(p,[month])})),values=points.flatMap(d=>series.map(([k])=>d[k])).filter(Number.isFinite);if(!values.length)return empty('No values supplied','Missing values remain blank.');const w=650,h=260,l=65,t=28,b=42,max=Math.max(...values,0),min=Math.min(...values,0),span=max-min||1,y=v=>t+(max-v)/span*(h-t-b),x=i=>l+i*(w-l-20)/Math.max(ms.length-1,1);return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(p.name)} monthly ${kind==='price'?'selling value':'production and sales'}"><line x1="${l}" x2="${w-20}" y1="${y(0)}" y2="${y(0)}" stroke="#dce5eb"/>${[0,.5,1].map(f=>`<text x="${l-8}" y="${y(min+f*span)+4}" text-anchor="end" font-size="10" fill="#657582">${num(min+f*span,1)}</text>`).join('')}${series.map(([k,n,c])=>points.map((d,i)=>{if(d[k]===null)return '';return `${i&&points[i-1][k]!==null?`<line x1="${x(i-1)}" y1="${y(points[i-1][k])}" x2="${x(i)}" y2="${y(d[k])}" stroke="${c}" stroke-width="2"/>`:''}<circle cx="${x(i)}" cy="${y(d[k])}" r="4" fill="${c}"><title>${esc(n)} · ${months[d.month]}: ${num(d[k],2)}</title></circle>`;}).join('')).join('')}${ms.map((m,i)=>`<text x="${x(i)}" y="${h-14}" text-anchor="middle" font-size="10" fill="#657582">${months[m]}</text>`).join('')}</svg><p class="source">${series.map(([,n])=>n).join(' · ')}. All supplied actual months in ${state.year}. Source cells are available in Monthly product detail.</p>`;}
products=function(){const defs=productDefinitions();if(!defs.length)return panel('Product economics','No product schedules supplied.',empty());const choices=[['budget',state.year+' budget'],...availableYears().filter(y=>y!==+state.year).map(y=>[String(y),y+' actual'])];if(!choices.some(([v])=>v===productComparison))productComparison='budget';if(!defs.some(p=>p.key===productSelection))productSelection=defs[0].key;const spec=productSpec();currentProducts=defs.map(p=>({...p,a:productMeasure(p),b:productMeasure(p,spec.months,spec.year,spec.type)}));const selected=currentProducts.find(p=>p.key===productSelection),withRevenue=currentProducts.filter(p=>p.rows.gross!==undefined),top=withRevenue.filter(p=>p.a.gross!==null).sort((a,b)=>b.a.gross-a.a.gross)[0],secondary=withRevenue.find(p=>/secondary|wastage/i.test(p.name)),sum=withRevenue.every(p=>p.a.gross!==null)?withRevenue.reduce((s,p)=>s+p.a.gross,0):null,total=val(27),difference=sub(sum,total),comparison=choices.find(([v])=>v===productComparison)[1];return `<div class="toolbar">${select('productComparison','Compare gross sales with',choices,productComparison)}</div><div class="cards">${card('Largest gross revenue share',pct(top?.a.share),esc(top?.name||'Unavailable'))}${card('Secondary revenue share',pct(secondary?.a.share),'Share of reported gross company sales')}${card('Reported product groups',withRevenue.length,'Groups with a gross-revenue source line')}${card('Product margin','—','Allocated product profit not supplied')}</div>`+panel('Which products are creating value?',`${esc(period())} · Revenue in ${unit()}; rates in BDT per kg. Select a product for source cells.`,table(['Product','Gross revenue','Product VAT','Revenue after VAT','Sales MT','Gross revenue share','Selling value / kg',esc(comparison)+' achieved'],currentProducts.map((p,i)=>[`<button data-product-evidence="${i}">${esc(p.name)}</button>`,money(p.a.gross),money(p.a.vat),money(p.a.net),num(p.a.volume,2),pct(p.a.share),num(p.a.selling,2),p.b.gross!==null&&p.b.gross>0&&p.a.gross!==null?pct(p.a.gross/p.b.gross*100):'—'])))+`<div class="notice">Revenue after VAT is before dealer commission and is calculated only when matched product VAT is supplied. Supplied price and indicative cost rates appear in the separate Net Sales Price analysis above. Product net profit remains unavailable without a reconciled cost allocation. Product labels follow the active SBU’s files. Revenue and volume are matched by product labels; differently named groups are kept separate.</div>`+panel('Product revenue reconciliation','Gross product revenue against the reported company sales subtotal. Missing product lines are not treated as zero.',table(['Measure',unit()],[['Product gross revenue total',money(sum)],['Reported company gross sales',money(total)],['Difference',money(difference)]]))+`<div class="toolbar">${select('productSelection','Product detail',defs.map(p=>[p.key,p.name]),productSelection)}</div><div class="grid">${panel(esc(selected.name)+' · selling value','BDT per kg calculated from income-statement revenue and sales MT. Supplied pricing rates are shown separately above.',productTrend(selected,'price'))}${panel(esc(selected.name)+' · production and sales','MT. Production less sales is a flow gap, not closing stock.',productTrend(selected,'volume'))}</div>`+panel('Monthly product detail',esc(selected.name)+' · selected reporting period. Select a month to inspect sources.',table(['Month','Gross revenue','VAT','Revenue after VAT','Sales MT','Production MT','Flow gap MT','Selling value / kg'],ids().map(m=>{const a=productMeasure(selected,[m]);return[`<button data-product-month="${m}">${months[m]} ${state.year}</button>`,money(a.gross),money(a.vat),money(a.net),num(a.volume,2),num(a.production,2),num(a.flow,2),num(a.selling,2)];})))+panel('Product review questions',esc(selected.name),table(['Question','Evidence'],[['Does selling value cover product cost?','Review the supplied monthly price-cost spread above; the cost allocation basis still requires validation.'],['Are sales above or below production?',selected.a.flow===null?'—':'Production less sales: '+num(selected.a.flow,2)+' MT'],['How do gross sales compare?',selected.a.gross===null||selected.b.gross===null?'—':money(selected.a.gross-selected.b.gross)+' '+unit()+' against '+esc(comparison)],['What would establish product profitability?','Matched materials, conversion, rejection, commission and overhead costs by product.']]))};
function productEvidence(p,selected=ids()){const spec=productSpec(),rows=[];for(const [type,year] of [['Actual',+state.year],[spec.type,spec.year]])for(const [field,r] of Object.entries(p.rows)){const kind=field==='vat'?'detail':'income';for(const m of selected){const rec=records[kind].find(x=>x.r===r&&x.year===year&&x.type===type&&x.month===m);rows.push([type,months[m]+' '+year,esc(field),esc(data[kind].name),esc(data[kind].sheet),rec?.cell||'—',num(rec?.value??null,4)]);}}$('evidenceBody').innerHTML=`<h2>${esc(p.name)}</h2><p>Revenue after VAT = gross product revenue − matched product VAT. Selling value/kg = revenue after VAT ÷ (sales MT × 1,000). Missing inputs remain blank. Values below are raw BDT or MT.</p>${table(['Series','Period','Measure','File','Worksheet','Cell','Value'],rows)}`;$('evidence').showModal();}
const priorProductBind=bind;bind=function(){priorProductBind();if(state.view!=='products')return;$('productComparison').onchange=e=>{productComparison=e.target.value;render();};$('productSelection').onchange=e=>{productSelection=e.target.value;render();};document.querySelectorAll('[data-product-evidence]').forEach(e=>e.onclick=()=>productEvidence(currentProducts[+e.dataset.productEvidence]));document.querySelectorAll('[data-product-month]').forEach(e=>e.onclick=()=>productEvidence(currentProducts.find(p=>p.key===productSelection),[+e.dataset.productMonth]));$('export').textContent='Export product economics';$('export').onclick=()=>{const rows=[['SBU',portfolio.sbus[activeSbu].name],['Period',period()],['Comparison',productComparison],['Product','Gross BDT','VAT BDT','After VAT BDT','Sales MT','Production MT','Selling BDT/kg','Cost BDT/kg','Spread BDT/kg','Comparison gross BDT'],...currentProducts.map(p=>[p.name,p.a.gross,p.a.vat,p.a.net,p.a.volume,p.a.production,p.a.selling,null,null,p.b.gross])],u=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='Product_Economics_'+state.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};};
